def prime_factorization(n):
    """Returns a dictionary of prime factors and their exponents for n."""
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def calculate_tau_n_to_12(n):
    """Calculates tau(n^12)."""
    if n == 1:
        # 1^12 = 1. tau(1) = 1.
        return 1

    factors_n = prime_factorization(n)

    tau_n_12 = 1
    for exponent in factors_n.values():
        # If n = p^e, n^12 = p^(12e). tau(n^12) = 12e + 1.
        tau_n_12 *= (12 * exponent + 1)

    return tau_n_12

solutions = []
for n in range(1, 1001):
    tau_val = calculate_tau_n_to_12(n)
    if n == tau_val:
        solutions.append(n)

print("Solutions found (n <= 1000):")
print(solutions)
